templates.template:
/* =============================================================================
   Skins N Things — a XenForo 2.3 port of the ProBoards "Skins N Things" skin by Allan of Skins n Things.
   Blue-grey textured page, a dark brown frame and title bars, blue category bars and cream rows.
   The skin's images are embedded below, so the style needs no uploads.
   ============================================================================= */
html
{
	background: url("data:image/png;base64,") repeat #96b5ce;
}

body,
.p-pageWrapper
{
	background: transparent;
}

// ---- The 800px framed column -------------------------------------------------------

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 800px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body
{
	background: transparent;
	border: none;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner
{
	background: url("data:image/png;base64,") center top / 800px 26px repeat-y;
	padding-left: 25px;
	padding-right: 25px;
}

.p-header
{
	padding-top: 12px;

	&::before
	{
		content: '';
		display: block;
		max-width: 800px;
		height: 26px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 800px 26px no-repeat;
	}
}

.p-header-content
{
	justify-content: center;
	padding: 4px 0 8px;
}

// The skin's banner replaces the logo. Delete this section to use the logo from Style properties.
.p-header-logo
{
	margin: 0 auto;

	img
	{
		display: none;
	}

	a
	{
		display: block;
		width: 750px;
		max-width: 100%;
		aspect-ratio: 750 / 100;
		background: url("data:image/jpeg;base64,") center / contain no-repeat;
	}
}

.p-navSticky,
.p-navSticky.is-sticky
{
	position: static !important;
}

// ---- Menu bar ---------------------------------------------------------------------------

.p-nav
{
	color: #f1e6df;
}

.p-nav-inner
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x content-box, url("data:image/png;base64,") center top / 800px 26px repeat-y;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #f1e6df;
		font-size: 11px;
		font-weight: 700;
		letter-spacing: 1px;
		text-transform: uppercase;
		text-shadow: 0 1px 1px rgba(0, 0, 0, .5);

		&:hover
		{
			color: #ffffff;
			text-decoration: none;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(255, 255, 255, .14);

		.p-navEl-link
		{
			color: #ffffff;
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #f1e6df;

	&:hover
	{
		background: rgba(255, 255, 255, .14);
		color: #ffffff;
		text-decoration: none;
	}
}

.p-sectionLinks-inner a,
.p-breadcrumbs a
{
	color: #94b3cc;
}

.p-body-inner
{
	color: #e6d6cc;
	padding-bottom: 16px;
}

.p-title-value,
.p-breadcrumbs
{
	color: #e6d6cc;
}

// ---- Blocks: the skin's category head, middle and base images around every block --------

.block-container
{
	background: url("data:image/png;base64,") center top / 100% 16px repeat-y;
	border: none;
	border-radius: 0;
	padding: 0 1%;

	&::before,
	&::after
	{
		content: '';
		display: block;
		height: 22px;
		margin: 0 -1%;
		background: url("data:image/png;base64,") center top / 100% 22px no-repeat;
	}

	&::after
	{
		height: 16px;
		background: url("data:image/png;base64,") center top / 100% 16px no-repeat;
	}
}

.block-body,
.block-row
{
	background: #efe7e1;
	color: #231914;
}

.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x, #3f2d22;
	border-bottom: 1px solid #795747;
	color: #f1e6df;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #f1e6df;
	}

	.block-desc
	{
		color: #f1e6df;
		opacity: .8;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: #f1e6df;
	opacity: .75;

	&:hover,
	&.is-active
	{
		opacity: 1;
		border-color: #f1e6df;
	}
}

.block-footer
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x, #3f2d22;
	border-top: 1px solid #795747;
	color: #f1e6df;

	a
	{
		color: #f1e6df;
	}
}

.node + .node
{
	border-top: 1px solid #795747;
}

.node-body,
.structItem
{
	background: #efe7e1;
}

.structItem
{
	border-top-color: #795747;
}

.node-title a,
.structItem-title a
{
	color: #446d8c;
	font-weight: 700;

	&:hover
	{
		color: #2c4d66;
	}
}

.node-description,
.node-meta,
.node-stats,
.structItem-minor
{
	color: #231914;
}

// Forum icons: the skin's new-posts image when there's something unread, otherwise no-new-posts.
.node--forum .node-icon i
{
	display: block;
	width: 29px;
	height: 29px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / contain no-repeat;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	background-image: url("data:image/png;base64,");
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: #446d8c;
	}
}

.message,
.message-inner
{
	background: #efe7e1;
	border-color: #795747;
}

.message-cell--user
{
	background: #e4d9d1;
	border-right-color: #795747;
}

.message-userArrow::after
{
	border-right-color: #efe7e1;
}

.button.button--primary,
a.button.button--primary
{
	background: url("data:image/gif;base64,") left top / auto 100% repeat-x;
	background-color: #463226;
	border: 1px solid #795747;
	color: #f1e6df;

	&:hover
	{
		color: #ffffff;
		filter: brightness(1.1);
	}
}

// ---- Footer: the frame's base, then the skin credit on the page ---------------------------

.p-footer
{
	background: transparent;
	color: #231914;

	&::before
	{
		content: '';
		display: block;
		max-width: 800px;
		height: 26px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 800px 26px no-repeat;
	}

	a
	{
		color: #231914;
	}
}

.p-footer-copyright::after
{
	content: "Skins N Things skin by Allan of Skins n Things";
	display: block;
	margin-top: 4px;
}

// ---- Narrower than the frame: plain column, scaled banner ------------------------------

@media (max-width: 819px)
{
	.p-header
	{
		padding-top: 0;

		&::before
		{
			content: none;
		}
	}

	.p-header-inner,
	.p-nav-inner,
	.p-sectionLinks-inner,
	.p-body-inner
	{
		background: #231914;
		padding-left: 8px;
		padding-right: 8px;
	}

	.p-nav-inner
	{
		background: url("data:image/gif;base64,") left top / auto 100% repeat-x;
	}

	.p-footer::before
	{
		background-size: 100% auto;
	}
}
